import React, { useState, useEffect } from "react";
import { useAppContext, actions } from "../context/AppContext";

const CountryInfo = () => {
  const { state, dispatch } = useAppContext();
  const [countryData, setCountryData] = useState(null);
  const [loading, setLoading] = useState(false);

  // Fetch country data when a country is selected
  useEffect(() => {
    if (!state.countries.selected) {
      setCountryData(null);
      return;
    }

    const fetchCountryData = async () => {
      setLoading(true);
      try {
        // Mock data for demonstration - replace with actual API call
        const mockData = {
          name: state.countries.selected,
          capital: "Mock Capital",
          population: "10,000,000",
          area: "500,000 km²",
          continent: "Mock Continent",
          languages: ["English", "Local Language"],
          currency: "Mock Currency",
          timezone: "UTC+0",
          coordinates: { lat: 0, lng: 0 },
        };

        // Simulate API delay
        await new Promise((resolve) => setTimeout(resolve, 500));
        setCountryData(mockData);
      } catch (error) {
        console.error("Error fetching country data:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchCountryData();
  }, [state.countries.selected]);

  if (!state.ui.showCountryInfo || !state.countries.selected) {
    return null;
  }

  return (
    <div className="fixed top-4 right-4 z-50 bg-space-purple bg-opacity-90 text-white p-6 rounded-xl shadow-2xl backdrop-blur-md max-w-sm">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold">Country Info</h2>
        <button
          onClick={() => dispatch(actions.selectCountry(null))}
          className="text-gray-300 hover:text-white transition-colors"
          title="Close"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full"></div>
        </div>
      ) : countryData ? (
        <div className="space-y-4">
          {/* Country Name and Flag */}
          <div className="flex items-center space-x-3 mb-4">
            <img
              src={`/flags/${countryData.name}.png`}
              alt={`${countryData.name} flag`}
              className="w-12 h-8 object-cover rounded border border-gray-600"
              onError={(e) => {
                e.target.style.display = "none";
              }}
            />
            <h3 className="text-lg font-semibold text-blue-300">
              {countryData.name}
            </h3>
          </div>

          {/* Country Details */}
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-gray-400">Capital:</span>
                <p className="font-medium">{countryData.capital}</p>
              </div>
              <div>
                <span className="text-gray-400">Population:</span>
                <p className="font-medium">{countryData.population}</p>
              </div>
              <div>
                <span className="text-gray-400">Area:</span>
                <p className="font-medium">{countryData.area}</p>
              </div>
              <div>
                <span className="text-gray-400">Continent:</span>
                <p className="font-medium">{countryData.continent}</p>
              </div>
            </div>

            <div className="text-sm">
              <span className="text-gray-400">Languages:</span>
              <p className="font-medium">{countryData.languages.join(", ")}</p>
            </div>

            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-gray-400">Currency:</span>
                <p className="font-medium">{countryData.currency}</p>
              </div>
              <div>
                <span className="text-gray-400">Timezone:</span>
                <p className="font-medium">{countryData.timezone}</p>
              </div>
            </div>

            <div className="text-sm">
              <span className="text-gray-400">Coordinates:</span>
              <p className="font-medium font-mono">
                {countryData.coordinates.lat.toFixed(4)}°,{" "}
                {countryData.coordinates.lng.toFixed(4)}°
              </p>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="pt-4 border-t border-gray-600 space-y-2">
            <button
              onClick={() => {
                // Focus camera on country
                console.log("Focus on country:", countryData.name);
              }}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-lg transition-colors text-sm"
            >
              🎯 Focus on Country
            </button>

            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => {
                  // Show more details
                  console.log("Show more details for:", countryData.name);
                }}
                className="bg-gray-700 hover:bg-gray-600 text-white py-2 px-3 rounded-lg transition-colors text-xs"
              >
                📊 Details
              </button>
              <button
                onClick={() => {
                  // Show on map
                  console.log("Show on map:", countryData.name);
                }}
                className="bg-gray-700 hover:bg-gray-600 text-white py-2 px-3 rounded-lg transition-colors text-xs"
              >
                🗺️ Map View
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="text-center py-4 text-gray-400">
          <p>No country data available</p>
        </div>
      )}
    </div>
  );
};

export default CountryInfo;
